import EventEmitter from 'events';

import LoggerProxy from '../common/logs/logger-proxy';
import type {
  E2eeKey,
  E2eeRosterMember,
  E2eeSignalingSource,
  IMlsHttpClient,
  MLSConfig,
  SframeParams,
} from './types';
import type {
  EpochInfo,
  HTTPRequest,
  ModuleInstance,
  RosterMember,
  Transaction,
  TransactionResult,
  WebE2EEInstance,
} from './wasm';

// WASM log levels, indexed by the numeric level the engine emits (see LogLevel in libe2ee).
const WASM_LOG_LEVELS = ['', 'FATAL', 'ERROR', 'WARN', 'INFO', 'DEBUG'];

/** Payloads for each event emitted by {@link MLS}. */
export interface MLSEventMap {
  joinSuccess: {epoch: number; securityCode: string; sframe: SframeParams; key: E2eeKey};
  joinFailure: {reason: string};
  mediaEncryptionServiceFailure: {errorCode: number; message: string};
  newKey: E2eeKey;
  useKey: {epoch: number};
  purgeKeys: {epoch: number};
  rosterAdded: E2eeRosterMember[];
  rosterRemoved: {urls: string[]};
  leaderChanged: {isLeader: boolean};
  evicted: void;
  versionNegotiated: {version: number};
  securityCodeChanged: {code: string};
}

export type MLSEvent = keyof MLSEventMap;

/**
 * Pure MLS protocol engine wrapping the WebE2EE WASM module. It has no webex/HTTP/LLM
 * dependencies: all I/O flows through the injected {@link IMlsHttpClient}, and all outputs are
 * emitted as typed events. This keeps it unit-testable in isolation.
 */
export default class MLS {
  private readonly module: ModuleInstance;

  private readonly httpClient: IMlsHttpClient;

  private readonly emitter = new EventEmitter();

  private readonly transactions = new Map<string, Transaction['type']>();

  private e2ee: WebE2EEInstance | null = null;

  private readonly waitTimeouts = new Set<ReturnType<typeof setTimeout>>();

  private lastSecurityCode = '';

  /**
   * @param {Object} deps
   * @param {ModuleInstance} deps.module - The loaded WASM module used to instantiate the engine.
   * @param {IMlsHttpClient} deps.httpClient - Transport for the engine's protocol requests.
   */
  constructor({httpClient, module}: {httpClient: IMlsHttpClient; module: ModuleInstance}) {
    this.httpClient = httpClient;
    this.module = module;
  }

  /**
   * Subscribe to an engine event.
   * @param {MLSEvent} event
   * @param {Function} listener
   * @returns {void}
   */
  on<K extends MLSEvent>(event: K, listener: (payload: MLSEventMap[K]) => void): void {
    this.emitter.on(event, listener as (payload: unknown) => void);
  }

  /**
   * Unsubscribe from an engine event.
   * @param {MLSEvent} event
   * @param {Function} listener
   * @returns {void}
   */
  off<K extends MLSEvent>(event: K, listener: (payload: MLSEventMap[K]) => void): void {
    this.emitter.off(event, listener as (payload: unknown) => void);
  }

  /**
   * @param {MLSEvent} event
   * @param {*} [payload]
   * @returns {void}
   */
  private emitEvent<K extends MLSEvent>(event: K, payload?: MLSEventMap[K]): void {
    LoggerProxy.logger.info(`e2ee: MLS --> emitting event: ${event}`);
    this.emitter.emit(event, payload);
  }

  /**
   * Instantiates the engine, wires its callbacks, and applies credentials, trust anchors and
   * timeouts. Must be called before {@link join}.
   * @param {MLSConfig} config
   * @returns {void}
   */
  initialize(config: MLSConfig): void {
    LoggerProxy.logger.info('e2ee: MLS --> initialize: instantiating engine');
    if (this.e2ee) {
      LoggerProxy.logger.info('e2ee: MLS --> initialize: already initialized');

      return;
    }

    this.e2ee = new this.module.WebE2EE();
    this.setupCallbacks();

    this.e2ee.initialize(
      config.participantId,
      config.deviceUrl,
      config.deviceType,
      config.correlationId,
      config.displayName,
      config.serviceUrl
    );

    if (config.credentials) {
      const {privateKey, certChain} = config.credentials;

      this.e2ee.addX509Credential(privateKey, certChain);
    }

    if (config.trustAnchors) {
      this.e2ee.setTrustAnchors(
        config.trustAnchors.webexCaRoots || '',
        config.trustAnchors.domainNameRoots || '',
        config.trustAnchors.userIdentityRoots || '',
        config.trustAnchors.domainNameRootsP7b || new Uint8Array()
      );
    }

    if (config.joinTimeout !== undefined) {
      this.e2ee.setJoinTimeout(config.joinTimeout);
    }
    if (config.coalesceWindow !== undefined) {
      this.e2ee.setCoalesceWindow(config.coalesceWindow);
    }

    LoggerProxy.logger.info('e2ee: MLS --> initialize: engine initialized');
  }

  /**
   * @returns {void}
   */
  private setupCallbacks(): void {
    const {e2ee} = this;

    if (!e2ee) {
      return;
    }

    e2ee.setOnNewTransaction(({id, type}: Transaction) => {
      this.transactions.set(id, type);
    });

    e2ee.setOnCompleteTransaction((id, result: TransactionResult) => {
      const transactionType = this.transactions.get(id);

      if (!transactionType) {
        LoggerProxy.logger.warn(`e2ee: MLS --> completion for unknown transaction (id=${id})`);

        return;
      }

      this.transactions.delete(id);

      if (result.status === 'join_success') {
        if (transactionType !== 'join') {
          LoggerProxy.logger.warn(
            `e2ee: MLS --> join success for non-join transaction (id=${id}, type=${transactionType})`
          );

          return;
        }

        this.lastSecurityCode = result.sec_code;
        this.emitEvent('joinSuccess', {
          epoch: result.epoch,
          securityCode: result.sec_code,
          sframe: {
            cipherSuite: result.sframe_cipher_suite,
            epochBits: result.sframe_epoch_bits,
          },
          key: {
            epoch: result.epoch,
            baseKey: new Uint8Array(result.base_key),
            index: result.index,
            indexBits: result.index_bits,
            canEncrypt: false,
          },
        });
      } else if (result.status === 'update_success') {
        if (transactionType !== 'update') {
          LoggerProxy.logger.warn(
            `e2ee: MLS --> update success for non-update transaction (id=${id}, type=${transactionType})`
          );
        }
      } else if (result.status === 'failure') {
        if (transactionType === 'join') {
          this.emitEvent('joinFailure', {reason: result.reason});
        } else {
          LoggerProxy.logger.error(
            `e2ee: MLS --> update transaction failed (id=${id}, reason=${result.reason})`
          );
        }
      }
    });

    e2ee.setOnHttpRequest((request: HTTPRequest) => {
      const {url, handlerId} = request;
      // The body is a view into WASM memory that is only valid during this callback, so copy it now.
      const body = new Uint8Array(request.body);

      // Complete asynchronously so the engine is never re-entered from inside its own request call.
      Promise.resolve()
        .then(() => this.sendHttpRequest(url, body))
        .then((responseBytes) => {
          this.completeHttpRequest(handlerId, true, responseBytes, 0, '');
        })
        .catch((error) => {
          const errorCode = MLS.getMesErrorCode(error);
          const message = error?.message || 'Request failed';

          LoggerProxy.logger.warn(
            `e2ee: MLS --> HTTP request failed (url=${url}, errorCode=${errorCode}): ${message}`
          );
          this.completeHttpRequest(handlerId, false, new Uint8Array(0), errorCode, message);
        });
    });

    e2ee.setOnWait((milliseconds, handlerId) => {
      const timeout = setTimeout(() => {
        this.waitTimeouts.delete(timeout);
        this.e2ee?.completeWait(handlerId);
      }, milliseconds);

      this.waitTimeouts.add(timeout);
    });

    e2ee.setOnGotKey((epoch: EpochInfo) => {
      this.emitEvent('newKey', {
        epoch: epoch.epoch,
        baseKey: new Uint8Array(epoch.base_key),
        index: epoch.index,
        indexBits: epoch.index_bits,
        canEncrypt: false, // the key can only be used for encryption after onUseKey is called
      });
    });

    e2ee.setOnUseKey((epoch: number) => {
      this.emitEvent('useKey', {epoch});
      this.emitSecurityCodeIfChanged();
    });

    e2ee.setOnPurgeBefore((epoch: number) => {
      this.emitEvent('purgeKeys', {epoch});
    });

    e2ee.setOnLeader(() => {
      this.emitEvent('leaderChanged', {isLeader: true});
    });

    e2ee.setOnAddRoster((added: RosterMember[]) => {
      this.emitEvent('rosterAdded', added.map(MLS.toRosterMember));
      this.emitSecurityCodeIfChanged();
    });

    e2ee.setOnRemoveRoster((removed: string[]) => {
      this.emitEvent('rosterRemoved', {urls: removed});
      this.emitSecurityCodeIfChanged();
    });

    e2ee.setOnEvicted(() => {
      this.emitEvent('evicted');
    });

    e2ee.setOnE2eeVersion((version: number) => {
      this.emitEvent('versionNegotiated', {version});
    });

    e2ee.setOnMissingCommit((mlsEpoch, useKeyEpoch) => {
      LoggerProxy.logger.warn(
        `e2ee: MLS --> missing commit (mlsEpoch=${mlsEpoch}, useKeyEpoch=${useKeyEpoch})`
      );
    });

    e2ee.setOnLog((level: number, message: string) => {
      const label = WASM_LOG_LEVELS[level] ?? '';

      switch (level) {
        case 1:
        case 2:
          LoggerProxy.logger.error(`e2ee: [E2EE ${label}] ${message}`);
          break;
        case 3:
          LoggerProxy.logger.warn(`e2ee: [E2EE ${label}] ${message}`);
          break;
        case 5:
          LoggerProxy.logger.debug(`e2ee: [E2EE ${label}] ${message}`);
          break;
        default:
          LoggerProxy.logger.info(`e2ee: [E2EE ${label}] ${message}`);
      }
    });
  }

  /**
   * Sends an engine HTTP request through the injected {@link IMlsHttpClient}, converting between
   * the engine's JSON bytes and the client's objects. Conversion failures reject so the engine's
   * request is completed as failed.
   * @param {string} url - The absolute request URL provided by the engine.
   * @param {Uint8Array} body - JSON request payload as bytes (owned copy, not a WASM memory view).
   * @returns {Promise<Uint8Array>} JSON response payload as bytes.
   */
  private async sendHttpRequest(url: string, body: Uint8Array): Promise<Uint8Array> {
    const requestBody = MLS.decodeRequestBody(url, body);
    const response = await this.httpClient.request(url, requestBody);

    return MLS.encodeResponseBody(url, response);
  }

  /**
   * @param {string} url - Request URL, used only for logging.
   * @param {Uint8Array} body - JSON request payload as bytes.
   * @returns {unknown} the parsed request body.
   * @throws {Error} when the bytes are not valid JSON.
   */
  private static decodeRequestBody(url: string, body: Uint8Array): unknown {
    try {
      return JSON.parse(new TextDecoder().decode(body));
    } catch (error) {
      LoggerProxy.logger.error(
        `e2ee: MLS --> failed to parse engine HTTP request body as JSON (url=${url}): ${error?.message}`
      );
      throw new Error(`Invalid JSON in HTTP request body: ${error?.message}`);
    }
  }

  /**
   * @param {string} url - Request URL, used only for logging.
   * @param {unknown} response - Response object from the HTTP client.
   * @returns {Uint8Array} the response serialized as JSON bytes.
   * @throws {Error} when the response cannot be serialized to JSON.
   */
  private static encodeResponseBody(url: string, response: unknown): Uint8Array {
    try {
      return new TextEncoder().encode(JSON.stringify(response));
    } catch (error) {
      LoggerProxy.logger.error(
        `e2ee: MLS --> failed to serialize HTTP response body as JSON (url=${url}): ${error?.message}`
      );
      throw new Error(`Unserializable HTTP response body: ${error?.message}`);
    }
  }

  /**
   * Hands a media-encryption service request outcome back to the engine. libe2ee throws
   * `e2ee_negotiation_failure` out of this call when it can't recover from the service's error code
   * or fails to process a successful response; this surfaces in JS as an opaque value with no
   * message. That is unrecoverable for the in-flight operation, so it is reported as
   * `mediaEncryptionServiceFailure` instead of escaping as an unhandled rejection.
   * @param {number} handlerId
   * @param {boolean} success
   * @param {Uint8Array} body
   * @param {number} errorCode - Media-encryption service error code, or 0 when not applicable.
   * @param {string} message
   * @returns {void}
   */
  private completeHttpRequest(
    handlerId: number,
    success: boolean,
    body: Uint8Array,
    errorCode: number,
    message: string
  ): void {
    try {
      this.e2ee?.completeHttpRequest(handlerId, success, body, errorCode, message);
    } catch (error) {
      LoggerProxy.logger.error(
        `e2ee: MLS --> engine threw while completing HTTP request (success=${success}, errorCode=${errorCode}): ${error}`
      );
      this.emitEvent('mediaEncryptionServiceFailure', {
        errorCode,
        message: success ? 'Engine failed to process HTTP response' : message,
      });
    }
  }

  /**
   * @param {*} error - Rejection from the HTTP client.
   * @returns {number} the media-encryption service error code from the response body, or 0.
   */
  private static getMesErrorCode(error: any): number {
    const errorCode = error?.body?.errorCode;

    return Number.isInteger(errorCode) ? errorCode : 0;
  }

  /**
   * @returns {void}
   */
  private emitSecurityCodeIfChanged(): void {
    const code = this.getSecurityCode();

    if (code && code !== this.lastSecurityCode) {
      this.lastSecurityCode = code;
      this.emitEvent('securityCodeChanged', {code});
    }
  }

  /**
   * Starts the MLS join.
   * @returns {void}
   */
  join(): void {
    LoggerProxy.logger.info('e2ee: MLS --> join: starting MLS join');
    this.assertInitialized().join();
  }

  /**
   * Leaves the MLS group.
   * @returns {void}
   */
  leave(): void {
    LoggerProxy.logger.info('e2ee: MLS --> leave: leaving MLS group');
    this.transactions.clear();
    this.assertInitialized().leave();
  }

  /**
   * Detaches engine callbacks and releases the WASM engine and wrapper resources.
   * @returns {void}
   */
  cleanUp(): void {
    this.waitTimeouts.forEach((timeout) => clearTimeout(timeout));
    this.waitTimeouts.clear();
    this.transactions.clear();
    this.lastSecurityCode = '';

    const {e2ee} = this;

    this.e2ee = null;

    if (e2ee) {
      e2ee.setOnNewTransaction(null);
      e2ee.setOnCompleteTransaction(null);
      e2ee.setOnHttpRequest(null);
      e2ee.setOnWait(null);
      e2ee.setOnGotKey(null);
      e2ee.setOnUseKey(null);
      e2ee.setOnLeader(null);
      e2ee.setOnPurgeBefore(null);
      e2ee.setOnEvicted(null);
      e2ee.setOnAddRoster(null);
      e2ee.setOnRemoveRoster(null);
      e2ee.setOnE2eeVersion(null);
      e2ee.setOnMissingCommit(null);
      e2ee.setOnLog(null);
      e2ee.delete();
    }

    this.emitter.removeAllListeners();
  }

  /**
   * Forwards an incoming MLS protocol event (from the signaling channel) to the engine.
   * @param {Uint8Array} eventData
   * @param {E2eeSignalingSource} source - Which channel the event arrived on, logged for diagnostics.
   * @returns {void}
   */
  handleEvent(eventData: Uint8Array, source: E2eeSignalingSource): void {
    LoggerProxy.logger.info(
      `e2ee: MLS --> handleEvent: forwarding ${eventData.length} bytes from ${source} to engine`
    );
    this.assertInitialized().handle(new Uint8Array(eventData));
  }

  /**
   * Tells the engine whether the signaling channel was already connected before join.
   * @param {boolean} connected
   * @returns {void}
   */
  setLlmConnectedBeforeJoin(connected: boolean): void {
    LoggerProxy.logger.info(`e2ee: MLS --> setLlmConnectedBeforeJoin: ${connected}`);
    this.assertInitialized().setLlmConnectedBeforeJoin(connected);
  }

  /**
   * Notifies the engine that the signaling channel is now connected.
   * @returns {void}
   */
  llmConnected(): void {
    LoggerProxy.logger.info('e2ee: MLS --> llmConnected');
    this.assertInitialized().llmConnected();
  }

  /**
   * @returns {string} the current security code, or '' if not initialized.
   */
  getSecurityCode(): string {
    return this.e2ee ? this.e2ee.securityCode() : '';
  }

  /**
   * @returns {E2eeRosterMember[]} the current MLS roster, or [] if not initialized.
   */
  getRoster(): E2eeRosterMember[] {
    return this.e2ee ? this.e2ee.roster().map(MLS.toRosterMember) : [];
  }

  /**
   * @returns {boolean} whether this client is the group leader.
   */
  isLeader(): boolean {
    return this.e2ee ? this.e2ee.isLeader() : false;
  }

  /**
   * @returns {WebE2EEInstance}
   */
  private assertInitialized(): WebE2EEInstance {
    if (!this.e2ee) {
      throw new Error('MLS not initialized');
    }

    return this.e2ee;
  }

  /**
   * @param {RosterMember} member - raw WASM roster member.
   * @returns {E2eeRosterMember}
   */
  private static toRosterMember(member: RosterMember): E2eeRosterMember {
    return {
      deviceUrl: member.url,
      displayName: member.display_name,
      deviceType: member.device_type,
      validationResult: member.validation_result,
      ...(member.x509 && {
        identityResults: member.x509.map((certificateResult) => ({
          result: certificateResult.result,
          certificateChain: certificateResult.member_certs.map((certificate) => ({
            primaryName: certificate.primary_name,
            commonName: certificate.common_name,
            organizationName: certificate.organization_name,
            emailAddresses: certificate.email_addresses,
            domainNames: certificate.domain_names,
            notBefore: certificate.not_before,
            notAfter: certificate.not_after,
            signatureAlgorithm: certificate.signature_algorithm,
            publicKeyAlgorithm: certificate.public_key_algorithm,
            identityType: certificate.identity_type,
            der: new Uint8Array(certificate.der),
          })),
          ...(certificateResult.failed_cert_index !== undefined && {
            failedCertIndex: certificateResult.failed_cert_index,
          }),
        })),
      }),
    };
  }
}
